import{c as a,Q as n,j as s,m as e}from"./chunks/framework.DOi4mjdC.js";const l="/assets/%E8%BE%93%E5%85%A5%E4%B8%BAbfloat16_t%E7%B1%BB%E5%9E%8B%E7%9A%84Add%E8%AE%A1%E7%AE%97%E6%B5%81%E7%A8%8B.BYDWv__b.png",_=JSON.parse('{"title":"TBuf的使用","description":"","frontmatter":{},"headers":[{"level":1,"title":"TBuf的使用","slug":"tbuf的使用"},{"level":2,"title":"算子类实现","slug":"算子类实现"}],"relativePath":"guide/算子实践参考/SIMD算子实现/矢量编程/TBuf的使用.md","filePath":"guide/算子实践参考/SIMD算子实现/矢量编程/TBuf的使用.md"}'),o={name:"guide/算子实践参考/SIMD算子实现/矢量编程/TBuf的使用.md"};function p(i,t,c,r,u,d){return n(),s("div",null,[...t[0]||(t[0]=[e('<h1 id="tbuf的使用" tabindex="-1">TBuf的使用 <a class="header-anchor" href="#tbuf的使用" aria-label="Permalink to &quot;TBuf的使用&quot;">​</a></h1><p>在大多数算子开发时，核函数计算过程需要使用临时内存来存储运算的中间结果，这些中间结果以临时变量表示，临时变量占用的内存可以使用TBuf数据结构来管理，具体介绍请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/TBuf.md" target="_blank" rel="noreferrer">TBuf</a>。下文将以输入的数据类型为bfloat16_t、在单核上运行的Add算子为例，介绍TBuf的使用方式。本样例中介绍的算子完整代码请参见<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/04_resource_management/tmp_buffer" target="_blank" rel="noreferrer">使用临时内存的Add算子样例</a>。</p><p>在Atlas A2 训练系列产品/Atlas 800I A2 推理产品上，<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Add.md" target="_blank" rel="noreferrer">Add</a>接口不支持对数据类型bfloat16_t的源操作数进行求和计算。因此，需要先将算子输入的数据类型转换成Add接口支持的数据类型，再进行计算。为保证计算精度，调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Cast.md" target="_blank" rel="noreferrer">Cast</a>接口将输入bfloat16_t类型转换为float类型，再进行Add计算，并在计算结束后将float类型转换回bfloat16_t类型。</p><p>通过以上分析，得到Ascend C Add算子的设计规格如下：</p><ul><li><p>算子类型（OpType）：Add</p></li><li><p>算子输入输出：</p><p><strong>表 1</strong> Add算子输入输出规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;name&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;shape&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;data type&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;&lt;strong&gt;format&lt;/strong&gt;&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;x（输入）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(1, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;bfloat16_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;y（输入）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(1, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;bfloat16_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;z（输出）&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;(1, 2048)&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;bfloat16_t&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>核函数名称：tmp_buffer_custom</p></li><li><p>使用的主要接口：</p><ul><li>DataCopy：数据搬移接口</li><li>Cast：矢量精度转换接口</li><li>Add：矢量基础算术接口</li><li>EnQue、DeQue等接口：Queue队列管理接口</li></ul></li><li><p>算子实现文件名称：tmp_buffer.asc</p></li></ul><h2 id="算子类实现" tabindex="-1">算子类实现 <a class="header-anchor" href="#算子类实现" aria-label="Permalink to &quot;算子类实现&quot;">​</a></h2><p>该样例的CopyIn，CopyOut任务与<a href="./基础矢量算子.html">基础矢量算子</a>相同，Compute任务的具体流程如下图所示。</p><p><strong>图 1</strong> 输入为bfloat16_t类型的Add计算流程<br><img src="'+l+`" alt="" title="输入为bfloat16_t类型的Add计算流程"></p><p>在Compute任务中，表示Cast转换结果、Add计算结果的临时变量均需要使用临时内存存储。与<a href="./基础矢量算子.html#zh-cn_topic_0000002201157438_section10423482111">基础矢量算子实现</a>的KernelAdd算子类相比，本样例新增两个TBuf类型的成员变量tmpBuf0、tmpBuf1，用于管理计算过程中使用的临时内存，代码如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>class KernelAdd {</span></span>
<span class="line"><span>public:</span></span>
<span class="line"><span>    __aicore__ inline KernelAdd() {}</span></span>
<span class="line"><span>    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, AscendC::TPipe* pipeIn){}</span></span>
<span class="line"><span>    __aicore__ inline void Process(){}</span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    __aicore__ inline void CopyIn(){}</span></span>
<span class="line"><span>    __aicore__ inline void Compute(){}</span></span>
<span class="line"><span>    __aicore__ inline void CopyOut(){}</span></span>
<span class="line"><span>private:</span></span>
<span class="line"><span>    AscendC::TPipe* pipe;</span></span>
<span class="line"><span>    AscendC::TQue&lt;AscendC::TPosition::VECIN, 1&gt; inQueueX;</span></span>
<span class="line"><span>    AscendC::TQue&lt;AscendC::TPosition::VECIN, 1&gt; inQueueY;</span></span>
<span class="line"><span>    AscendC::TQue&lt;AscendC::TPosition::VECOUT, 1&gt; outQueueZ;</span></span>
<span class="line"><span>    AscendC::TBuf&lt;AscendC::TPosition::VECCALC&gt; tmpBuf0;     </span></span>
<span class="line"><span>    AscendC::TBuf&lt;AscendC::TPosition::VECCALC&gt; tmpBuf1;</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;bfloat16_t&gt; xGm; </span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;bfloat16_t&gt; yGm;</span></span>
<span class="line"><span>    AscendC::GlobalTensor&lt;bfloat16_t&gt; zGm;</span></span>
<span class="line"><span>};</span></span></code></pre></div><p>初始化函数阶段除原有步骤外，需要调用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/InitBuffer.md" target="_blank" rel="noreferrer">InitBuffer</a>接口为TBuf变量分配内存，具体的初始化函数代码如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z, AscendC::TPipe* pipeIn)</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    pipe = pipeIn;</span></span>
<span class="line"><span>    xGm.SetGlobalBuffer((__gm__ bfloat16_t*)x, TOTAL_LENGTH);</span></span>
<span class="line"><span>    yGm.SetGlobalBuffer((__gm__ bfloat16_t*)y, TOTAL_LENGTH);</span></span>
<span class="line"><span>    zGm.SetGlobalBuffer((__gm__ bfloat16_t*)z, TOTAL_LENGTH);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(inQueueX, 1, TOTAL_LENGTH * sizeof(bfloat16_t));</span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(inQueueY, 1, TOTAL_LENGTH * sizeof(bfloat16_t));</span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(outQueueZ, 1, TOTAL_LENGTH * sizeof(bfloat16_t));</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(tmpBuf0, TOTAL_LENGTH * sizeof(float));</span></span>
<span class="line"><span>    pipe-&gt;InitBuffer(tmpBuf1, TOTAL_LENGTH * sizeof(float));</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>基于矢量编程范式，核函数需要实现3个基本任务：CopyIn，Compute，CopyOut。与<a href="./基础矢量算子.html#zh-cn_topic_0000002201157438_section10423482111">基础矢量算子实现</a>相同，Process函数按顺序调用CopyIn函数，Compute函数，CopyOut函数。其中，CopyIn函数，CopyOut函数与<a href="./基础矢量算子.html#zh-cn_topic_0000002201157438_zh-cn_topic_0000001514531781_li10182173751518">基础矢量算子的CopyIn函数</a>、<a href="./基础矢量算子.html#zh-cn_topic_0000002201157438_zh-cn_topic_0000001514531781_li1134112320247">基础矢量算子的CopyOut函数</a>的实现没有差异，此处不过多赘述。Compute函数的实现步骤如下：</p><ol><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/DeQue.md" target="_blank" rel="noreferrer">DeQue</a>从VECIN的Queue中取出LocalTensor。</li><li>使用TBuf.<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Get.md" target="_blank" rel="noreferrer">Get</a>从TBuf上获取全部长度的Tensor作为临时内存。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Cast.md" target="_blank" rel="noreferrer">Cast</a>接口将LocalTensor转换为float类型，并存入临时内存。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Add.md" target="_blank" rel="noreferrer">Add</a>接口完成矢量计算，将计算结果存入临时内存。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Cast.md" target="_blank" rel="noreferrer">Cast</a>接口将临时内存中的计算结果转换为bfloat16_t类型。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/EnQue.md" target="_blank" rel="noreferrer">EnQue</a>将bfloat16_t类型的结果LocalTensor放入VECOUT的Queue中。</li><li>使用<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/FreeTensor.md" target="_blank" rel="noreferrer">FreeTensor</a>释放不再使用的LocalTensor。</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline void Compute()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;bfloat16_t&gt; xLocal = inQueueX.DeQue&lt;bfloat16_t&gt; ();</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;bfloat16_t&gt; yLocal = inQueueY.DeQue&lt;bfloat16_t&gt; ();</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;bfloat16_t&gt; zLocal = outQueueZ.AllocTensor&lt;bfloat16_t&gt; ();</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;float&gt; tmpTensor0 = tmpBuf0.Get&lt;float&gt;();</span></span>
<span class="line"><span>    AscendC::LocalTensor&lt;float&gt; tmpTensor1 = tmpBuf1.Get&lt;float&gt;();</span></span>
<span class="line"><span>    </span></span>
<span class="line"><span>    AscendC::Cast(tmpTensor0, xLocal, AscendC::RoundMode::CAST_NONE, TOTAL_LENGTH);</span></span>
<span class="line"><span>    AscendC::Cast(tmpTensor1, yLocal, AscendC::RoundMode::CAST_NONE, TOTAL_LENGTH);</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>    AscendC::Add(tmpTensor0, tmpTensor0, tmpTensor1, TOTAL_LENGTH);</span></span>
<span class="line"><span>    AscendC::Cast(zLocal, tmpTensor0, AscendC::RoundMode::CAST_RINT, TOTAL_LENGTH);</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>    outQueueZ.EnQue&lt;bfloat16_t&gt;(zLocal);</span></span>
<span class="line"><span>    inQueueX.FreeTensor(xLocal);</span></span>
<span class="line"><span>    inQueueY.FreeTensor(yLocal);</span></span>
<span class="line"><span>}</span></span></code></pre></div>`,15)])])}const f=a(o,[["render",p]]);export{_ as __pageData,f as default};
